CREATE TABLE session_archives (
        key TEXT PRIMARY KEY, archived_at TEXT NOT NULL
    )

CREATE UNIQUE INDEX history_input_identity ON history_entries (
        session_key, json_extract(record, '$.content.input_id')
    ) WHERE kind='input'

CREATE INDEX sessions_subagent_origin_turn_id ON sessions (
        json_extract(metadata, '$.parent_session_key'), json_extract(metadata, '$.subagent_task.origin_turn_id')
    ) WHERE json_extract(metadata, '$.session_type')='subagent' AND json_type(metadata, '$.parent_session_key')='text' AND json_type(metadata, '$.subagent_task.origin_turn_id')='text'
